using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;

namespace CET6Word {
 public static class V2Tests {
  static void Check(bool value,string why="assertion failed"){if(!value)throw new Exception(why);}
  public static AppState Legacy(){string raw;using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("v1-builtin.json"))using(var r=new StreamReader(s))raw=r.ReadToEnd();var book=StateStore.Json().Deserialize<Vocabulary>(raw);var state=new AppState{CurrentVocabulary=book.Id};state.Vocabularies.Add(book);state.Notebooks.Add(new Notebook{Id="default",Name="默认收藏"});return state;}
  static void Round(LearningEngine e,string id,bool correct){e.EndSession();e.StartWith(new List<string>{id},false,"test");e.Submit(correct?e.Find(id).English:"wrong-answer");e.Next();}
  public static void Run(Action<string,Action> test,string root){
   test("MIG: merge all old IDs, unmatched entries, custom data and records without loss",()=>{var old=Legacy();var e=new LearningEngine(old,7);e.StudyWords();var matched=old.Vocabularies[0].Words[0];var unmatched=old.Vocabularies[0].Words.First(w=>!Program.LoadBuiltin().Words.Any(n=>n.English==w.English));e.Learn(matched.Id);e.Master(unmatched.Id,true);e.ToggleFavorite(unmatched.Id);var b=e.AddNotebook("旧词本");e.PutInNotebook(b,matched.Id);var custom=VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\nabandon,自定义释义"),"独立").Vocabulary;old.Vocabularies.Add(custom);e.Learn(custom.Words[0].Id);e.Sort("random",matched.Id);e.SetAnchor(unmatched.Id);Round(e,matched.Id,false);Round(e,matched.Id,true);old.Settings.AutoRead=true;var next=UpgradeMigration.Merge(old,Program.LoadBuiltin(),StateStore.Encode(old));UpgradeMigration.CheckPreserved(old,next);Check(next.Vocabularies[0].Words.Count==3002);Check(next.Migrations[0].Matched==301&&next.Migrations[0].Unmatched==47&&next.Migrations[0].Added==2654);Check(next.Vocabularies[0].Words.Single(w=>w.Id==unmatched.Id).Formal==false);Check(next.Vocabularies[1].Words[0].Meaning=="自定义释义");Check(next.Positions[old.CurrentVocabulary].RandomOrder.Take(348).SequenceEqual(old.Positions[old.CurrentVocabulary].RandomOrder));Check(!next.Progress.ContainsKey(next.Vocabularies[0].Words.First(w=>!old.Vocabularies[0].Words.Any(o=>o.Id==w.Id)).Id));File.WriteAllText(Path.Combine(root,"migration-fixture.json"),StateStore.Encode(next));});
   test("MIG: repeated upgrade is idempotent",()=>{var once=UpgradeMigration.Merge(Legacy(),Program.LoadBuiltin());var twice=UpgradeMigration.Merge(once,Program.LoadBuiltin());Check(StateStore.Equivalent(StateStore.Encode(once),StateStore.Encode(twice)));});
   test("MIG: full raw backup verified, new disk state verified, source hash recorded",()=>{using(var store=new StateStore(Path.Combine(root,"migration-native"))){store.Save(Legacy());var raw=File.ReadAllText(store.FilePath);AppState next;Check(UpgradeMigration.Apply(store,store.Load(Legacy),Program.LoadBuiltin(),out next));var report=next.Migrations.Last();var backup=store.ReadBackup(Path.Combine(store.DirectoryPath,report.BackupFile));Check(backup.SchemaVersion==1&&report.PreviousSha256==UpgradeMigration.Sha256(raw));Check(store.Load(Legacy).SchemaVersion==2);Check(!UpgradeMigration.Apply(store,next,Program.LoadBuiltin(),out next));Check(Directory.GetFiles(store.DirectoryPath,"*.cet6backup").Length==1);}});
   test("MIG: failed atomic commit keeps old state and readable backup",()=>{using(var store=new StateStore(Path.Combine(root,"migration-rollback"))){store.Save(Legacy());var raw=File.ReadAllText(store.FilePath);Directory.CreateDirectory(store.FilePath+".previous");bool failed=false;try{AppState unused;UpgradeMigration.Apply(store,store.Load(Legacy),Program.LoadBuiltin(),out unused);}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(store.FilePath)==raw);var backup=Directory.GetFiles(store.DirectoryPath,"*.cet6backup").Single();Check(store.ReadBackup(backup).SchemaVersion==1);}});
   test("MIG: same spelling across libraries and identity conflicts do not merge",()=>{var old=Legacy();var duplicate=old.Vocabularies[0].Words[0];old.Vocabularies[0].Words.Add(new Word{Id="old-homograph",English=duplicate.English,Meaning="另一个旧义项"});old.Progress["old-homograph"]=new Progress{Mastered=true};var fresh=Program.LoadBuiltin();var custom=VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\nabandon,自定义"),"custom").Vocabulary;custom.Words[0].Id=fresh.Words.First(w=>w.Id.StartsWith("v2-")).Id;old.Vocabularies.Add(custom);var next=UpgradeMigration.Merge(old,fresh);Check(next.Migrations.Last().Conflicts.Count==1);Check(next.Vocabularies[0].Words.Count(w=>w.English==duplicate.English)==3);Check(next.Progress["old-homograph"].Mastered);StateStore.Validate(next);});
   test("MIG: incomplete legacy answers remain unknown and raw history survives",()=>{var old=Legacy();var id=old.Vocabularies[0].Words[0].Id;var e=new LearningEngine(old);Round(e,id,true);var raw=StateStore.Json().DeserializeObject(StateStore.Encode(old)) as Dictionary<string,object>;var sessions=(object[])raw["Sessions"];var q=(Dictionary<string,object>)sessions[0];var a=(Dictionary<string,object>)((object[])q["Attempts"])[0];a.Remove("Correct");a.Remove("At");old=StateStore.Decode(StateStore.Json().Serialize(raw));Check(old.Sessions[0].LegacyIncomplete&&!old.Sessions[0].Attempts[0].ResultKnown);var next=UpgradeMigration.Merge(old,Program.LoadBuiltin());var migrated=new LearningEngine(next);Check(migrated.Evidence(id).LastCorrect==null&&!migrated.Recited().Any(w=>w.Id==id));Check(next.Sessions[0].LegacyRecordJson.Contains("Answer"));migrated.Master(id,true);Check(migrated.Recited().Any(w=>w.Id==id));Check(next.Sessions[0].Attempts[0].At==0);});
   test("MIG: participation-only and timestamp-less master evidence stay conservative",()=>{var old=Legacy();var id=old.Vocabularies[0].Words[0].Id;old.Sessions.Add(new Session{Id="participation",VocabularyId=old.CurrentVocabulary,Words=new List<string>{id},Attempts=null,Finished=100});old.Progress[id]=new Progress{LearnedAt=100,LearnCount=9,Mastered=true};var raw=StateStore.Encode(old);var normalized=StateStore.Decode(raw);var next=UpgradeMigration.Merge(normalized,Program.LoadBuiltin());var e=new LearningEngine(next);Check(e.Evidence(id).Mastered&&e.Evidence(id).SuccessAt==0&&e.Evidence(id).LastCorrect==null);e.Master(id,false);Check(!e.Recited().Any(w=>w.Id==id));Check(next.Sessions.Count==1&&next.Sessions[0].Attempts==null);});
   test("MIG/REC: a new reliable answer supersedes timeless captured history without inventing dates",()=>{var old=Legacy();var id=old.Vocabularies[0].Words[0].Id;old.Sessions.Add(new Session{Id="timeless-old",VocabularyId=old.CurrentVocabulary,Words=new List<string>{id},Attempts=null});var normalized=StateStore.Decode(StateStore.Encode(old));var next=UpgradeMigration.Merge(normalized,Program.LoadBuiltin());var e=new LearningEngine(next);Check(e.Evidence(id).LastCorrect==null);Round(e,id,true);Check(e.Evidence(id).LastCorrect==true&&e.Recited().Any(w=>w.Id==id));Round(e,id,false);Check(e.Evidence(id).LastCorrect==false&&!e.Recited().Any(w=>w.Id==id));Check(next.Sessions[0].Finished==0&&next.Sessions[0].Attempts==null&&next.Sessions[0].LegacyRecordJson==normalized.Sessions[0].LegacyRecordJson);Check(next.Migrations[0].LegacySessionIds.SequenceEqual(new[]{"timeless-old"}));StateStore.Validate(StateStore.Decode(StateStore.Encode(next)));});
   test("REC: first correct qualifies, later wrong removes, master overrides wrong",()=>{var e=new LearningEngine(Program.CreateState());var id=e.Current.Words[0].Id;Round(e,id,false);Round(e,id,true);Check(e.Recited().Any(w=>w.Id==id)&&e.State.Errors[id].Pending&&e.State.Errors[id].Streak==1);Round(e,id,false);Check(!e.Recited().Any(w=>w.Id==id));e.Master(id,true);Check(e.Recited("mastered").Any(w=>w.Id==id)&&!e.Recited("correct").Any(w=>w.Id==id));e.Master(id,false);Check(!e.Recited().Any(w=>w.Id==id));Round(e,id,true);e.Master(id,true);Check(e.Recited().Count(w=>w.Id==id)==1);e.Master(id,false);Check(e.Recited("correct").Any(w=>w.Id==id));});
   test("REC: active learning is not success; recent timestamps and unknown fallback stable",()=>{var e=new LearningEngine(Program.CreateState());var a=e.Current.Words[0].Id;var b=e.Current.Words[1].Id;var c=e.Current.Words[2].Id;e.Learn(a);Check(e.Recited().Count==0);e.State.Progress[a].Mastered=true;Round(e,b,true);e.Master(c,true);e.State.Progress[c].MasteredAt=e.State.Sessions.Last().Attempts.Last().At+1;Check(e.Recited()[0].Id==c&&e.Recited().Last().Id==a);Check(e.Recited("all","original").Select(w=>w.Id).SequenceEqual(new[]{a,b,c}));Check(e.Evidence(a).SuccessAt==0);});
   test("SEARCH: full formal book substring includes mastered; no state mutations",()=>{var e=new LearningEngine(Program.CreateState());e.Master(e.Current.Words[0].Id,true);e.ToggleFavorite(e.Current.Words[0].Id);var before=StateStore.Encode(e.State);Check(e.SearchEnglish("ABAND").Any(w=>w.Id==e.Current.Words[0].Id));Check(e.SearchEnglish("放弃").Count==0);Check(StateStore.Equivalent(before,StateStore.Encode(e.State)));});
   test("BR: anchor migration, page jumps, size bounds and last/empty pages",()=>{var e=new LearningEngine(Program.CreateState());var p=new ReadingPosition{Anchor=e.Current.Words[47].Id};var page=WordPage.Build(e.Current.Words,20,p);Check(page.Page==3&&page.Offset==7&&page.Words[7].Id==p.Anchor);WordPage.Jump(p,2,page.TotalPages);Check(WordPage.Build(e.Current.Words,20,p).Words[0].Id==e.Current.Words[20].Id);bool bad=false;try{WordPage.Jump(p,0,10);}catch(ArgumentException){bad=true;}Check(bad);Check(WordPage.Build(new List<Word>(),20,new ReadingPosition()).TotalPages==1);Check(WordPage.Build(e.Current.Words,20,new ReadingPosition{Page=999},false).Words.Count==15);});
   test("BR: mastery fills current page and restores fixed/random without reshuffling",()=>{var e=new LearningEngine(Program.CreateState(),123);var old=e.StudyWords();e.Master(old[4].Id,true);var page=WordPage.Build(e.StudyWords(),20,new ReadingPosition());Check(page.Words.Count==20&&page.Words.Last().Id==old[20].Id);e.Master(old[4].Id,false);Check(e.StudyWords().Select(w=>w.Id).SequenceEqual(old.Select(w=>w.Id)));e.Sort("random",null);var order=e.StudyWords().Select(w=>w.Id).ToList();e.Master(order[7],true);Check(e.StudyWords().Select(w=>w.Id).SequenceEqual(order.Where(id=>id!=order[7])));e.Master(order[7],false);Check(e.StudyWords().Select(w=>w.Id).SequenceEqual(order));});
  }
 }
}
